/**
 * Club 프로필 이미지 업로드
 */

export type UploadClubProfileImageParams = {
  clubId: ClubId
  file: File
}

interface UploadClubProfileImageResponse {
  imageUrl: string
}

const uploadClubProfileImage = async ({ clubId, file }: UploadClubProfileImageParams, token: string) => {
  const formData = new FormData()
  formData.append('image', file)

  const response = await axios.post<UploadClubProfileImageResponse>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/profile-image`,
    formData,
    {
      headers: {
        Authorization: token,
        'Content-Type': 'multipart/form-data'
      }
    }
  )
  return response.data
}

export const useUploadClubProfileImage = (): UseMutationResult<
  UploadClubProfileImageResponse,
  unknown,
  UploadClubProfileImageParams,
  void
> => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const queryClient = useQueryClient()

  const mutationFn = (values: UploadClubProfileImageParams) => uploadClubProfileImage(values, token)

  return useMutation('uploadClubProfileImage', mutationFn, {
    onSuccess: (_data, values) => {
      enqueueSnackbar(COMMON_MESSAGE.UPDATE_SUCCESS, { variant: 'success' })
      queryClient.invalidateQueries(['clubInformation', values.clubId])
    },
    onError: error => {
      if (axios.isAxiosError(error) && error.response?.status === 413) {
        enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.TOO_LARGE, { variant: 'error' })
      } else if (axios.isAxiosError(error) && error.response?.status === 400) {
        enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.WRONG_FORMAT, { variant: 'error' })
      } else {
        enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.UPLOAD_FAIL, { variant: 'error' })
      }

      throw error
    }
  })
}

