import { useSnackbar } from 'notistack'
import { useRef, useState } from 'react'

import DeleteIcon from '@mui/icons-material/Delete'
import UploadIcon from '@mui/icons-material/Upload'
import { Box, Button, CardMedia, Typography } from '@mui/material'

import { IMAGE_UPLOAD_MESSAGE } from 'src/data/messages'

import type { ClubId } from 'src/models/club'

import { useGetClubInformation } from 'src/hooks/api/club'
import { useDeleteClubProfileImage, useUploadClubProfileImage } from 'src/hooks/api/settings'

import ImagePreviewModal from './ImagePreviewModal'

interface ClubProfileImageProps {
  clubId: ClubId
}

const ClubProfileImage: React.FC<ClubProfileImageProps> = ({ clubId }) => {
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [previewImage, setPreviewImage] = useState<string | null>(null)
  const [selectedFile, setSelectedFile] = useState<File | null>(null)
  const [isModalOpen, setIsModalOpen] = useState(false)

  const { enqueueSnackbar } = useSnackbar()
  const { data: clubData } = useGetClubInformation(clubId)
  const uploadMutation = useUploadClubProfileImage()
  const deleteMutation = useDeleteClubProfileImage()

  const currentImageUrl = clubData?.profileImageUrl

  const handleFileSelect: React.ChangeEventHandler<HTMLInputElement> = e => {
    const file = e.target.files?.[0]
    if (!file) return

    // 파일 크기 검증 (5MB = 5242880 bytes)
    const MAX_FILE_SIZE = 5242880
    if (file.size > MAX_FILE_SIZE) {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.TOO_LARGE, { variant: 'error' })
      // input 초기화
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
      return
    }

    // 파일 타입 검증
    const ALLOWED_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
    if (!ALLOWED_TYPES.includes(file.type)) {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.WRONG_FORMAT, { variant: 'error' })
      // input 초기화
      if (fileInputRef.current) {
        fileInputRef.current.value = ''
      }
      return
    }

    // 미리보기 이미지 생성
    const reader = new FileReader()

    reader.onload = () => {
      if (reader.result && typeof reader.result === 'string') {
        setPreviewImage(reader.result)
        setSelectedFile(file)
        setIsModalOpen(true)
      } else {
        enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.UPLOAD_FAIL, { variant: 'error' })
      }
    }

    reader.onerror = () => {
      enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.UPLOAD_FAIL, { variant: 'error' })
    }

    reader.readAsDataURL(file)

    // input 초기화 (같은 파일 재선택 가능하도록)
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
  }

  const handleUploadButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    fileInputRef.current?.click()
  }

  const handleConfirmUpload = async () => {
    if (!selectedFile) return

    try {
      await uploadMutation.mutateAsync({ clubId, file: selectedFile })
      handleCloseModal()
    } catch (error) {
      // useMutation의 onError에서 처리됨
    }
  }

  const handleCloseModal = () => {
    setIsModalOpen(false)
    setPreviewImage(null)
    setSelectedFile(null)
  }

  const handleDelete: React.MouseEventHandler<HTMLButtonElement> = async () => {
    try {
      await deleteMutation.mutateAsync({ clubId })
    } catch (error) {
      // useMutation의 onError에서 처리됨
    }
  }

  // 서버의 현재 이미지 표시
  const displayImageUrl = currentImageUrl

  return (
    <Box mb={2}>
      <Typography variant={'h4'} mb={2}>
        동아리 프로필 이미지
      </Typography>

      <Box display="flex" flexDirection="column" gap={2} alignItems="center">
        {displayImageUrl && (
          <Box
            sx={{
              width: 150,
              height: 150,
              borderRadius: '50%',
              overflow: 'hidden',
              border: '1px solid',
              borderColor: 'divider'
            }}
          >
            <CardMedia
              component="img"
              sx={{
                width: '100%',
                height: '100%',
                objectFit: 'cover'
              }}
              image={displayImageUrl}
              alt="동아리 프로필 이미지"
            />
          </Box>
        )}

        <input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/jpg,image/png,image/webp"
          style={{ display: 'none' }}
          onChange={handleFileSelect}
        />

        <Box display="flex" gap={1} justifyContent="center">
          <Button
            variant="outlined"
            startIcon={<UploadIcon />}
            onClick={handleUploadButtonClick}
            disabled={uploadMutation.isLoading}
          >
            이미지 선택
          </Button>
          {currentImageUrl && (
            <Button
              variant="outlined"
              color="error"
              startIcon={<DeleteIcon />}
              onClick={handleDelete}
              disabled={deleteMutation.isLoading}
            >
              삭제
            </Button>
          )}
        </Box>

        <Typography variant="caption" color="text.secondary" textAlign="center">
          jpg, jpeg, png, webp 형식의 이미지만 업로드 가능합니다. (최대 5MB)
        </Typography>
      </Box>

      <ImagePreviewModal
        isOpen={isModalOpen}
        imageUrl={previewImage}
        isUploading={uploadMutation.isLoading}
        onClose={handleCloseModal}
        onConfirm={handleConfirmUpload}
      />
    </Box>
  )
}

export default ClubProfileImage
